func:
// The style block sits once in flow context and is embedded by the headline view - that way it applies to the whole page.
// The empty payload also clears the message areas: the dashboard remembers the last content per node id, and after a rebuild an area would otherwise show what an earlier node left behind.
flow.set('stil', "<style>
/* System font as on macOS and iOS, with a fallback */
.sdi, .sdi * {
    font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI",
                 Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    box-sizing: border-box;
}
/* Colours by measured contrast, not by example.
 *
 * The light grey came from Apple interfaces - where it sits on larger
 * type. Brought down to 13 pixels, #86868b gave only 3.62:1 against white;
 * 4.5:1 is required, and it only becomes legible noticeably above that.
 * Every value below has been measured and is given in brackets, so that
 * later changes are not chosen by feel again.
 */
.sdi {
    --akzent: #0071e3;   /* 4.70 on white */
    --gut: #1e8e3e;      /* darker than #34c759, which gave only 2.3 on white */
    --warten: #b45309;
    --schlecht: #c62828;
    --text: #1d1d1f;     /* 16.9 */
    --grau: #55565a;     /* 7.33 on white, 6.73 on the card */
    --linie: #d2d2d7;
    --flaeche: #ffffff;
    --hinter: #f5f5f7;
    color: var(--text);
    font-size: 15px;
    line-height: 1.45;
}

/* --- Headings ---------------------------------------------------------- */
.sdi-titel {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--grau);
    margin: 0 0 14px;
}

/* --- The big number ---------------------------------------------------- */
.sdi-zahl {
    font-size: 56px;
    font-weight: 600;
    letter-spacing: -0.02em;
    line-height: 1.05;
    font-variant-numeric: tabular-nums;
}
.sdi-einheit { font-size: 17px; font-weight: 400; color: var(--grau); margin-left: 8px; }
.sdi-unterzeile { color: var(--grau); font-size: 13px; margin-top: 6px; }

/* --- Attributes as chips ----------------------------------------------- */
.sdi-chips { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 12px; }
.sdi-chip {
    font-size: 12px; font-weight: 500; padding: 4px 10px; border-radius: 100px;
    background: var(--hinter); color: var(--text);
}
.sdi-chip-an { background: rgba(0,113,227,0.1); color: var(--akzent); }

/* --- Tables ------------------------------------------------------------ */
.sdi-tabelle { width: 100%; border-collapse: collapse; font-size: 14px; }
.sdi-tabelle th {
    text-align: left; font-weight: 500; font-size: 12px; color: var(--grau);
    padding: 0 12px 8px; border-bottom: 1px solid var(--linie);
}
.sdi-tabelle td {
    padding: 11px 12px; border-bottom: 1px solid rgba(210,210,215,0.5);
}
.sdi-tabelle tr:last-child td { border-bottom: none; }
.sdi-rechts { text-align: right; font-variant-numeric: tabular-nums; }
/* The general header rule (.sdi-tabelle th) is more specific than
 * .sdi-rechts and overrode its right alignment: the heading "kg CO2 eq"
 * stood at the left edge of its column with the figures below at the right,
 * two finger widths apart. A heading that does not stand over its figures
 * no longer relates anything to anything. */
.sdi-tabelle th.sdi-rechts { text-align: right; }
.sdi-name { font-weight: 500; }
.sdi-leise { color: var(--grau); font-size: 13px; }

/* --- Share bars --------------------------------------------------------- */
.sdi-balken {
    height: 5px; border-radius: 100px; background: var(--hinter);
    overflow: hidden; min-width: 56px;
}
.sdi-balken > div { height: 100%; border-radius: 100px; background: var(--akzent); }

/* --- State dots --------------------------------------------------------- */
.sdi-punkt {
    display: inline-block; width: 9px; height: 9px; border-radius: 50%;
    margin-right: 9px; vertical-align: 1px;
}
.sdi-punkt-gut { background: var(--gut); }
.sdi-punkt-warten { background: var(--warten); }
.sdi-punkt-leer { background: var(--linie); }
/* Red means: looked and found nothing. Grey means: not looked yet. The
 * difference matters - in the one case one waits, in the other something
 * is missing. */
.sdi-punkt-fehlt { background: var(--schlecht); }
/* Blue: present, but product-wide - it holds for the assembled product, not
 * for the single part. */
.sdi-punkt-produkt { background: var(--akzent); }

/* --- Notice areas ------------------------------------------------------- */
.sdi-hinweis {
    border-radius: 12px; padding: 12px 14px; font-size: 14px;
    display: flex; gap: 10px; align-items: flex-start;
}
.sdi-hinweis-lauf { background: rgba(255,159,10,0.12); }
.sdi-hinweis-fehler { background: rgba(255,59,48,0.1); }
.sdi-hinweis-ruhe { background: var(--hinter); color: var(--grau); }
.sdi-hinweis code {
    font-family: "SF Mono", Consolas, monospace; font-size: 12px;
    background: rgba(0,0,0,0.05); padding: 1px 5px; border-radius: 5px;
}

/* --- Comparison --------------------------------------------------------- */
.sdi-vergleich {
    margin-top: 18px; padding: 14px; border-radius: 12px;
    background: var(--hinter); font-size: 14px;
}
.sdi-pfeil { color: var(--grau); margin: 0 8px; }
.sdi-mehr { color: var(--schlecht); font-weight: 600; }
.sdi-weniger { color: var(--gut); font-weight: 600; }

/* --- Disclosure rows ---------------------------------------------------- */
/* Disclosure rows looked like body text: 13 pixels with a tiny triangle in
 * front. Anyone not looking for them found the content behind only by
 * chance - and what is not found might as well not be there. They are now
 * set-off rows with a border, a surface and a mark at the far right:
 * recognisable as a control, without pulling attention from what matters. */
.sdi details { margin-top: 16px; }
.sdi summary {
    cursor: pointer; font-size: 14px; color: var(--text, #1d1d1f);
    font-weight: 500; padding: 11px 14px; list-style: none;
    /* A fixed colour, not a variable: in one of the cards the border was reset
     * to the text colour despite a fallback being given - a black border
     * between two grey ones. The border is too conspicuous to depend on a
     * variable resolving; the dark mode is served by its own rule further
     * down. */
    border: 1px solid #d2d2d7; border-radius: 10px;
    background: var(--flaeche, #ffffff);
    display: flex; align-items: center; justify-content: space-between;
    gap: 12px;
    transition: background 0.15s ease, border-color 0.15s ease;
}
.sdi summary:hover { background: #f5f5f7; border-color: #55565a; }
.sdi summary::-webkit-details-marker { display: none; }
/* The mark sits on the right, where nobody overlooks it on a disclosure
 * row, and turns when it opens. */
.sdi summary:after {
    content: "⌄"; font-size: 15px; line-height: 1; color: var(--grau, #55565a);
    transition: transform 0.15s ease;
}
.sdi details[open] summary { border-color: #55565a; }
.sdi details[open] summary:after { transform: rotate(180deg); }
.sdi details[open] > *:not(summary) { padding: 4px 2px 0; }

/* --- Dark appearance ---------------------------------------------------- */
/* In the dark the opposite holds: the same colours that were too pale on
 * white are too dark here. Blue and the state colours have to be lightened,
 * otherwise they vanish into the ground - #0071e3 would come to 3.62.
 *
 * What counts is the mode of the dashboard, not that of the browser. This
 * used to read @media (prefers-color-scheme: dark) - and that was exactly
 * why the text was barely legible: the browser reported dark while the
 * dashboard painted white. The light greys then stood on white ground at
 * 2.8:1. Vuetify sets the class on the enclosing element, and that one
 * tells the truth about the ground we sit on.
 */
.v-theme--dark .sdi,
.v-theme--nrdbDark .sdi {
        --akzent: #4a9eff;   /* 5.4 on the card, instead of 3.62 */
        --gut: #30d158;      /* 8.42 */
        --warten: #ffd60a;   /* 12.05 */
        --schlecht: #ff453a; /* 4.99 */
        --text: #f5f5f7;
        --grau: #aeaeb2;     /* 7.69 on the card, 6.30 on the background */
        --linie: #38383a;
        --flaeche: #1c1c1e; --hinter: #2c2c2e;
}
/* The tinted chips and notices need more opacity in the dark, otherwise
 * nothing of the hue is left. */
.v-theme--dark .sdi-hinweis code,
.v-theme--nrdbDark .sdi-hinweis code { background: rgba(255,255,255,0.08); }
.v-theme--dark .sdi-chip-an,
.v-theme--nrdbDark .sdi-chip-an { background: rgba(74,158,255,0.22); color: #7ab6ff; }
.v-theme--dark .sdi-hinweis-lauf,
.v-theme--nrdbDark .sdi-hinweis-lauf { background: rgba(255,214,10,0.14); }
.v-theme--dark .sdi-hinweis-fehler,
.v-theme--nrdbDark .sdi-hinweis-fehler { background: rgba(255,69,58,0.16); }
.sdi-einleitung {
    color: var(--grau, #55565a);
    font-size: 13px;
    line-height: 1.5;
    max-width: 620px;
    margin-bottom: 14px;
}
.sdi-bezug {
    font-size: 14px;
    color: var(--text, #1d1d1f);
    margin-top: 2px;
}
.sdi-verweis {
    color: inherit;
    text-decoration: none;
    border-bottom: 1px solid var(--rand, #e8e8ed);
}
.sdi-verweis:hover { color: var(--akzent, #0071e3); border-bottom-color: currentColor; }
.sdi-schritte { margin-top: 18px; max-width: 620px; }
.sdi-schritte > div {
    display: flex; gap: 12px; align-items: flex-start;
    font-size: 14px; line-height: 1.5; margin-bottom: 10px;
}
.sdi-schritte p { margin: 0; max-width: 600px; }
/* The numbered circles stood in --hinter on a white card: 1.09 to 1, that
 * is invisible. What was left were loose digits that could not be read as a
 * sequence. Filled in the accent colour they are clearly visible at 4.70,
 * and they tie the introduction visually to the button they lead to. */
.sdi-schritte span {
    flex: 0 0 22px; height: 22px; border-radius: 50%;
    background: var(--akzent); color: #fff;
    font-size: 12px; font-weight: 600;
    display: inline-flex; align-items: center; justify-content: center;
}
/* A fine line along the steps turns three rows into a path. */
.sdi-schritte { position: relative; padding-left: 2px; }
.sdi-schritte > div { position: relative; padding-bottom: 4px; }
.sdi-schritte > div:not(:last-child):after {
    content: ""; position: absolute; left: 11px; top: 24px; bottom: 0;
    width: 1px; background: var(--linie);
}
.sdi-hilfe { margin-top: 8px; }
.sdi-hilfe p { margin: 8px 0 0; max-width: 620px; }
.sdi-marke {
    display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap;
    font-size: 19px; font-weight: 600; letter-spacing: -0.01em;
    margin-bottom: 6px;
}
.sdi-marke span {
    font-size: 11px; font-weight: 600; letter-spacing: 0.06em;
    padding: 3px 8px; border-radius: 6px;
    background: rgba(0,113,227,0.1); color: var(--akzent);
}
.v-theme--dark .sdi-marke span, .v-theme--nrdbDark .sdi-marke span {
    background: rgba(74,158,255,0.22); color: #7ab6ff;
}
/* A message area with no message should not be left standing as a gap. */
.sdi-melde:has(> div:empty) { display: none !important; }
/* Moved here out of the control card: rules with an ancestor outside the
 * card are rewritten there and then apply always. In the dark the logo is
 * black on dark and hard to see; inverting it would misrepresent the mark,
 * a light backing plate behind it does not. */
.v-theme--dark .sdi-logo, .v-theme--nrdbDark .sdi-logo {
    background: #fff; border-radius: 8px; padding: 8px 12px;
}
</style>");
// Output 1 clears the areas that only show something during a run. Output 2 goes to the message area: that one stays visible and says nothing is running. An empty area without an explanation is a question in itself - one goes looking for the text that is missing.
return [{ payload: '' }, { payload: "<div class="sdi"><div class="sdi-hinweis sdi-hinweis-ruhe"><span class="sdi-punkt sdi-punkt-leer" style="margin-top:6px"></span><span><strong>No run in progress.</strong> Messages about each step of a run appear here, and stay until the next run starts.</span></div></div>" }];

// Fetches the list of administration shells for the dropdown.
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.url = AAS + '/shells';
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Builds the dropdown and keeps the preselection.
//
// The product is preselected rather than the first shell in the list: a
// user almost always wants to calculate the assembled product, not a
// single part.
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const schalen = ((msg.payload || {}).result || [])
    .map(s => s.idShort).filter(Boolean).sort();

msg.options = schalen.map(s => ({ label: s.replace(/_/g, ' '), value: s }));

// As with the method: always the shell in force as the payload, never the
// answer of the server. Otherwise the field shows one shell while another
// one is calculated.
const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
let gilt = (global.get('dashboardShell') || '').split('/').pop();
if (!gilt || schalen.indexOf(gilt) < 0) {
    gilt = schalen.indexOf(PRODUKT) >= 0 ? PRODUKT : schalen[0];
}
if (gilt) {
    global.set('dashboardShell', basis + '/' + gilt);
    flow.set('gewaehlteSchale', gilt);
    msg.payload = gilt;
}
return msg;

// Takes over the selection. The calculation flow reads it from global
// context, which is why it is put there and not only here.
const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const schale = String(msg.payload || '');
if (schale) {
    global.set('dashboardShell', basis + '/' + schale);
    flow.set('gewaehlteSchale', schale);
    node.status({ fill: 'blue', shape: 'dot', text: schale });
}
return null;

// Fetches the impact methods from openLCA for the dropdown.
const OLCA = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';
msg.url = OLCA;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', id: 1, method: 'data/get/descriptors',
                params: { '@type': 'ImpactMethod' } };
return msg;

// Builds the dropdown of methods and keeps the preselection.
const STANDARD = env.get('SDI_OPENLCA_DEFAULT_METHOD')
              || 'b4571628-4b7b-3e4f-81b1-9a8cca6cb3f8';
const methoden = ((msg.payload || {}).result || [])
    .filter(m => m && m.name)
    .sort((a, b) => a.name.localeCompare(b.name));

const nachId = {};
methoden.forEach(m => { nachId[m['@id']] = m.name; });
global.set('methodNamesById', nachId);

msg.options = methoden.map(m => ({ label: m.name, value: m['@id'] }));

// The payload always has to be the method in force.
//
// When one already stood in global context, the answer from openLCA used to
// stay here as the payload. The dropdown was then given a value it does not
// know, picked something, and reported that pick back - the calculation then
// ran with a method nobody had clicked, while the display named a third one.
// A result whose method cannot be read off it is worthless as evidence.
let gilt = (global.get('selectedMethods') || [])[0];
if (!gilt || !nachId[gilt]) { gilt = STANDARD; }
global.set('selectedMethods', [gilt]);
global.set('selectedMethodNames', [nachId[gilt] || 'default method']);
msg.payload = gilt;
return msg;

// Uebernimmt die gewaehlte Instanz.
const nummer = String(msg.payload || '');
if (nummer) {
    flow.set('gewaehlteInstanz', nummer);
    node.status({ fill: 'blue', shape: 'dot', text: nummer });
}
return null;

// Builds the dropdown of manufactured pieces.
//
// A product passport applies to a piece, not to a type. As long as the user
// interface knows only "Kugelschreiber TracePEN", it does not answer the
// question "what is inside this particular pen" - and that is exactly what
// someone scanning the QR code on it is asking.
//
// What is booked is offered. What was not booked does not exist as far as
// the passport is concerned; a dropdown with invented numbers would be worse
// than a short list.
const montagen = flow.get('montagen') || [];

// What is offered depends on the shell.
//
// For the assembled product it is the pens that were assembled. With a part
// selected it is that part's own pieces - the numbers that sit inside the
// pens. Before, the pen numbers always stood there, even under "Bolzen
// Aluminium"; the part being looked at could not be selected at all.
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
// The article numbers come from the nameplates that the source poll reads
// anyway - no longer from a table in the source code.
const ARTIKEL = flow.get('artikelNachSchale') || {};
const schale = flow.get('gewaehlteSchale') || PRODUKT;

let stuecke;
if (schale === PRODUKT) {
    stuecke = montagen.map(function (m) {
        return { nummer: m.stueck, zeit: m.zeit };
    });
} else {
    const artikel = ARTIKEL[schale] || '';
    stuecke = montagen.map(function (m) {
        const teil = (m.teile || []).find(function (k) { return k.artikel === artikel; });
        return teil ? { nummer: teil.nummer, zeit: m.zeit } : null;
    }).filter(Boolean);
}
stuecke.sort(function (a, b) { return String(b.zeit).localeCompare(String(a.zeit)); });

// The list is sent on every pass.
//
// Sending it only on a change was too frugal: after the page is reloaded or
// the shell is switched, the dropdown holds no entries any more while the
// string is the same - it then stayed empty. The value is still only set
// when the previous choice no longer belongs to the list; otherwise it would
// jump away under the user's hand.
msg.options = stuecke.map(function (s, i) {
    return { label: s.nummer + (i === 0 ? '  (latest)' : ''), value: s.nummer };
});
if (!stuecke.length) {
    msg.options = [{ label: 'no piece booked yet', value: '' }];
}
// The value always goes along.
//
// Without a value the dropdown sets its display to empty even though the
// list arrives - one then sees an empty dropdown beside a filled headline.
// Sending the same value again does no harm; only a different one would
// jump away under the user's hand.
const gewaehlt = flow.get('gewaehlteInstanz');
const gilt = stuecke.find(function (s) { return s.nummer === gewaehlt; });
msg.payload = gilt ? gilt.nummer : (stuecke[0] ? stuecke[0].nummer : '');
flow.set('gewaehlteInstanz', msg.payload);
return msg;

// Uebernimmt die gewaehlte Methode.
const id = String(msg.payload || '');
if (id) {
    const namen = global.get('methodNamesById') || {};
    global.set('selectedMethods', [id]);
    global.set('selectedMethodNames', [namen[id] || id]);
    node.status({ fill: 'blue', shape: 'dot', text: namen[id] || id });
}
return null;

// Receives whatever was pressed in the control area.
//
// Output 1: the chain, or a single step
// Output 2: the export as AASX
// Output 3: refresh the display
// Output 4: back to the initial state
const was = String(msg.topic || '');
if (was === 'export') { return [null, { topic: 'export', payload: 'export' }, null, null]; }
if (was === 'auffrischen') { return [null, null, { topic: 'start', payload: 'start' }, null]; }
if (was === 'leer') { return [null, null, null, { topic: 'leer', payload: '' }]; }
return [{ topic: was, payload: was }, null, null, null];

// Works through the sources one after another and checks every step.
//
// Output 1: start the step
// Output 2: after a short wait, look whether it delivered
// Output 3: message to the user interface
//
// One after another, not at the same time: the calculation needs the
// quantities from the ERP and the energies from simulation and machines.
const ALLE = ['erp', 'simulation', 'maschinen', 'rechnung'];
const NAMEN = {
    erp: 'ERP', simulation: 'Simulation',
    maschinen: 'Machine data', rechnung: 'Calculation',
    plm: 'PLM'
};

// A single step runs through the same machinery as the whole pass - the
// same check then applies to it. Two routes to the same end would be two
// routes that can drift apart.
const SCHRITTE = (msg.topic === 'kette' || flow.get('ketteEinzeln') === false)
    ? ALLE : (flow.get('ketteSchritte') || ALLE);
// How often to look, roughly ten seconds per attempt. The calculation is
// allowed to take longer than reading a bill of material.
const VERSUCHE = { erp: 6, simulation: 6, maschinen: 3, rechnung: 18 };

// Not every missing source is an error. Nothing is manufactured on a
// purchased part - refill, screw, spring - so there is nothing to measure
// there either. If the machine data stays away the run therefore carries on
// and notes that the manufacturing energy is missing; it is only aborted
// when a source is missing without which the result would be wrong.
//
// The ERP is a different matter: without quantities one calculates air.
const FREIWILLIG = ['maschinen'];

function meldung(art, text) {
    const klasse = art === 'fehler' ? 'sdi-hinweis-fehler'
                 : (art === 'lauf' ? 'sdi-hinweis-lauf' : 'sdi-hinweis-ruhe');
    return { payload: '<div class="sdi"><div class="sdi-hinweis ' + klasse
        + '">' + text + '</div></div>' };
}

// --- Start ---------------------------------------------------------------
// The PLM cannot be checked: it writes packages into a folder, not into the
// shell. It is only started here, and the user is told plainly that the
// interface cannot see when it is done.
if (msg.topic === 'plm') {
    return [{ topic: 'plm', payload: 'plm' }, null,
            meldung('lauf', '<span><strong>PLM</strong> is building the shells. '
                + 'This takes a few minutes, and the dashboard cannot see when '
                + 'it is done - watch the packages in the output folder.</span>'),
            null];
}

if (ALLE.indexOf(msg.topic) >= 0) {
    flow.set('ketteSchritte', [msg.topic]);
    flow.set('ketteEinzeln', true);
    flow.set('ketteIndex', 0);
    flow.set('ketteVersuch', 0);
    flow.set('ketteStart', new Date().toISOString());
    flow.set('ketteFehlend', []);
    return [{ topic: msg.topic, payload: msg.topic },
            { topic: 'pruefen', payload: msg.topic },
            meldung('lauf', '<span><strong>' + NAMEN[msg.topic]
                + '</strong> &hellip;</span>'),
            null];
}

if (msg.topic === 'kette') {
    flow.set('ketteSchritte', ALLE);
    flow.set('ketteEinzeln', false);
    flow.set('ketteIndex', 0);
    flow.set('ketteVersuch', 0);
    flow.set('ketteStart', new Date().toISOString());
    flow.set('ketteFehlend', []);
    const schritt = SCHRITTE[0];
    return [{ topic: schritt, payload: schritt },
            { topic: 'pruefen', payload: schritt },
            meldung('lauf', '<span><strong>Step 1 of ' + SCHRITTE.length
                + ':</strong> ' + NAMEN[schritt] + ' &hellip;</span>'),
            null];
}

// --- Answer of the check --------------------------------------------------
const index = flow.get('ketteIndex');
if (index === undefined || index === null) { return [null, null, null, null]; }
const schritt = SCHRITTE[index];

if (msg.gut) {
    const naechster = index + 1;
    if (naechster >= SCHRITTE.length) {
        flow.set('ketteIndex', null);
        // Skipped sources belong in the closing message. "All four steps
        // delivered" is wrong when one was empty and was passed over - and
        // that message is exactly what one reads later to find out what the
        // result rests on.
        const fehlend = flow.get('ketteFehlend') || [];
        const zusatz = fehlend.length
            ? ' <strong>' + fehlend.join(', ') + '</strong> delivered nothing '
              + 'and was left out, so the result does not include it.'
            : '';
        const wieviele = SCHRITTE.length - fehlend.length;
        return [null, null, { payload: '' },
                meldung(fehlend.length ? 'lauf' : 'ruhe',
                    '<span><strong>Done.</strong> '
                    + (SCHRITTE.length > 1
                        ? wieviele + ' of ' + SCHRITTE.length
                          + ' steps delivered data.'
                        : NAMEN[schritt] + ' delivered data.')
                    + zusatz + '</span>')];
    }
    flow.set('ketteIndex', naechster);
    flow.set('ketteVersuch', 0);
    const weiter = SCHRITTE[naechster];
    return [{ topic: weiter, payload: weiter },
            { topic: 'pruefen', payload: weiter },
            meldung('lauf', '<span><strong>Step ' + (naechster + 1) + ' of '
                + SCHRITTE.length + ':</strong> ' + NAMEN[weiter]
                + ' &hellip;</span>'),
            null];
}

// --- Nothing there yet: keep looking, but not forever --------------------
const versuch = (flow.get('ketteVersuch') || 0) + 1;
flow.set('ketteVersuch', versuch);
if (versuch < (VERSUCHE[schritt] || 6)) {
    return [null, { topic: 'pruefen', payload: schritt }, null, null];
}

// --- Stayed away: abort, or note it and carry on --------------------------
if (FREIWILLIG.indexOf(schritt) >= 0) {
    const uebersprungen = flow.get('ketteFehlend') || [];
    uebersprungen.push(NAMEN[schritt]);
    flow.set('ketteFehlend', uebersprungen);
    const naechster2 = index + 1;
    if (naechster2 >= SCHRITTE.length) {
        flow.set('ketteIndex', null);
        return [null, null, { payload: '' }, meldung('lauf',
            '<span><strong>' + NAMEN[schritt] + ': nothing found'
            + (flow.get('pruefSchale') ? ' in ' + flow.get('pruefSchale') : '')
            + '.</strong> Nothing is manufactured on a purchased part, so this '
            + 'is not an error. The run finished without it.</span>')];
    }
    flow.set('ketteIndex', naechster2);
    flow.set('ketteVersuch', 0);
    const weiter2 = SCHRITTE[naechster2];
    return [{ topic: weiter2, payload: weiter2 },
            { topic: 'pruefen', payload: weiter2 },
            meldung('lauf', '<span><strong>' + NAMEN[schritt]
                + ': nothing found</strong>'
                + (flow.get('pruefSchale') ? ' in ' + flow.get('pruefSchale') : '')
                + ' &mdash; continuing without it. Step ' + (naechster2 + 1)
                + ' of ' + SCHRITTE.length + ': ' + NAMEN[weiter2]
                + ' &hellip;</span>'),
            null];
}

flow.set('ketteIndex', null);
return [null, null, { payload: '' }, meldung('fehler',
    '<span><strong>' + NAMEN[schritt] + ' delivered no data'
    + (flow.get('pruefSchale') ? ' in ' + flow.get('pruefSchale') : '')
    + '.</strong> The run was stopped after ' + versuch + ' attempts, so the '
    + 'result is not calculated on incomplete data. Check whether the service '
    + 'is running and look at the messages below.</span>')];

// Reads the shell that the step just run must have filled.
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';
const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
// Where a source lands depends on the source, not on what is selected at
// the top:
//
//   ERP and simulation write into the product shell. A bill of material and
//   an order quantity concern the assembled product; a single screw has
//   neither.
//
//   Machine data sits in the shell of the part that was measured.
//
//   The calculation writes into the shell that was calculated - that is,
//   the selected one.
//
// This used to be the selected shell for everything. Whoever picked a part
// then got "ERP delivered no data", although the ERP had delivered
// properly - it was simply looked for in the wrong place. An error message
// pointing at a healthy system costs more time than none at all.
const GEWAEHLT = flow.get('gewaehlteSchale')
              || env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const BAUTEIL = env.get('SDI_LCA_MACHINE_PART') || 'Bolzen_Aluminium';

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const schritt = String(msg.payload || '');
flow.set('pruefSchritt', schritt);

// The calculation writes into the ILCD, the machine data into the part
// shell, everything else into the product.
let kennung;
if (schritt === 'rechnung') {
    kennung = BASIS + '/' + GEWAEHLT + '/ILCD';
} else if (schritt === 'maschinen') {
    // With a part selected its own measurement counts; otherwise that of
    // the configured part.
    kennung = BASIS + '/' + (GEWAEHLT === PRODUKT ? BAUTEIL : GEWAEHLT)
            + '/DataSources';
} else {
    kennung = BASIS + '/' + PRODUKT + '/DataSources';
}
flow.set('pruefSchale', kennung.split('/').slice(-2)[0]);

msg.url = AAS + '/submodels/' + b64(kennung);
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Decides whether the step delivered.
//
// It is not enough that data is present - it has to have come into being
// after the run started. Otherwise what was already there counts as a
// success, and the run carries on with old figures.
const schritt = flow.get('pruefSchritt');
const start = flow.get('ketteStart') || '';
const sm = msg.payload;

function finde(sammlung, name) {
    return ((sammlung || {}).value || []).find(e => e && e.idShort === name);
}
function wert(sammlung, name) {
    const e = finde(sammlung, name);
    return e ? e.value : null;
}

let gut = false;
let text = '';

if (schritt === 'rechnung') {
    const behaelter = ((sm && sm.submodelElements) || [{}])[0];
    for (const it of (behaelter.value || [])) {
        const zeit = wert(it, 'TimeOfLCA');
        if (zeit && String(zeit) >= start) { gut = true; text = String(zeit); }
    }
} else {
    let liste = null;
    for (const e of (sm && sm.submodelElements) || []) {
        if (e.idShort === 'DataSources') { liste = e; }
    }
    const WO = {
        erp: [['ERP', 'ERPData'], 'BillOfMaterial'],
        simulation: [['Simulation'], 'SimulationProcesses'],
        maschinen: [['MachineData', 'Manufacturing'], 'ManufacturingProcesses']
    }[schritt] || [[], ''];

    let quelle = null;
    for (const n of WO[0]) { quelle = quelle || finde(liste, n); }
    if (quelle) {
        const inhalt = ((finde(quelle, WO[1]) || {}).value) || [];
        const zeit = wert(quelle, 'TimeOfRetrieval');
        gut = inhalt.length > 0 && (!zeit || String(zeit) >= start);
        text = inhalt.length + ' entries in ' + (flow.get('pruefSchale') || '?')
             + ', written ' + String(zeit || '?');
    }
}

msg.gut = gut;
msg.payload = text;
node.status({ fill: gut ? 'green' : 'yellow', shape: 'dot',
              text: schritt + (gut ? ' ok' : ' waiting') });
return msg;

// Starts a flow through the admin interface of Node-RED.
// This way the user interface needs no wire into the other tabs - they
// stay untouched.
const KNOTEN = {
    "plm": "d360832dd00ed241",
    "erp": "a1b2c3d4e5f60000",
    "simulation": "b1c2d3e4f5a60000",
    "maschinen": "c1d2e3f4a5b60000",
    "rechnung": "sdikette000001"
};
const quelle = msg.topic || 'rechnung';
msg.url = (env.get('SDI_NODERED_URL') || 'http://localhost:1880')
        + '/inject/' + KNOTEN[quelle];
msg.method = 'POST';
msg.headers = {};
msg.payload = '';
node.status({ fill: 'blue', shape: 'dot', text: quelle });
return msg;

// Assembles the command for the export as AASX.
//
// The export is a program of its own, not a flow: it runs without Node-RED,
// and an adopter should be able to call it from the command line. The user
// interface calls that same program, so that there is only one route.
const ORDNER = env.get('SDI_EXPORT_DIR') || 'export';
const SKRIPT = env.get('SDI_EXPORT_SCRIPT') || '../src/export_aasx.py';
// Kept for the reply: the user has to learn where the files were written.
// They do not appear in the browser but on the machine running Node-RED -
// whoever expects a download otherwise searches the downloads folder in
// vain.
flow.set('exportOrdner', ORDNER);
msg.topic = 'export';
msg.payload = '"' + SKRIPT + '" "' + ORDNER + '" --split';
return msg;

// Reports what the export wrote.
const text = String(msg.payload || '');
const zeilen = text.split(/\r?\n/).filter(z => z.indexOf('.aasx') >= 0);
const anzahl = zeilen.length;
const fehler = (msg.rc && msg.rc.code) ? msg.rc.code : 0;

if (fehler || !anzahl) {
    msg.payload = '<div class="sdi"><div class="sdi-hinweis sdi-hinweis-fehler">'
        + '<span><strong>Export failed.</strong><br>'
        + text.substring(0, 300) + '</span></div></div>';
    // Output 2 raises a notification. A failure belongs in one too: whoever
    // starts the export and walks away otherwise finds only a folder with
    // nothing new in it.
    return [msg, { topic: 'Export failed',
                   payload: text.substring(0, 160) || 'no output' }];
}

// The folder as the program reported it, not as we guess it. If it reports
// none, the configured value stands.
let ordner = flow.get('exportOrdner') || 'export';
// The program reports the full path on a line of its own. Showing it
// matters more than the guess we would otherwise have to make.
const gemeldet = (text.match(/Writing to (.+)/) || [])[1];
if (gemeldet) { ordner = gemeldet.trim(); }

const ersteZeile = (zeilen[0] || '').trim();
// The backslash is fetched through its character code. Written as a
// character it does not survive the way into the flow file: it is resolved
// twice on the way, and what is left is an expression that fails on the
// click - a fault that only shows at the adopter.
const BS = String.fromCharCode(92);
const trenner = Math.max(ersteZeile.lastIndexOf('/'), ersteZeile.lastIndexOf(BS));
if (trenner > 0) { ordner = ersteZeile.slice(0, trenner); }

let liste = '';
for (const z of zeilen) {
    const teile = z.trim().split('/').join(BS).split(BS);
    liste += '<div class="sdi-leise">' + teile[teile.length - 1] + '</div>';
}

msg.payload = '<div class="sdi"><div class="sdi-hinweis sdi-hinweis-ruhe">'
    + '<span><strong>' + anzahl + ' packages written to '
    + '<code>' + ordner + '</code></strong> &mdash; on the machine running '
    + 'Node-RED, not as a browser download. Open them with the AASX Package '
    + 'Explorer.' + liste + '</span></div></div>';

// The export takes a while, and whoever started it is looking elsewhere in
// the meantime. The notification brings them back - with the full path,
// because without it the message is worthless: the files sit on the machine
// running Node-RED, not in the browser.
return [msg, {
    topic: 'Export finished',
    payload: anzahl + ' AASX packages written to<br><b>' + ordner + '</b>'
           + '<br>on the machine running Node-RED, not a browser download.'
}];

const runde = (flow.get('ergTakt') || 0) + 1;
flow.set('ergTakt', runde);
if (runde % 3 !== 0) { return null; }
return { topic: 'start', payload: 'start' };

// Polls what the data sources hold, one shell per pass.
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';
const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
// Two shells in turn: the product shell carries PLM, ERP and simulation, a
// part shell carries the machine data.
//
// Which part shell depends on the selection. With a part chosen at the top
// its own measurement counts - otherwise the row showed the values of the
// configured part while a quite different one was selected above. One then
// reads a figure that says nothing about the part in view.
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const GEWAEHLT = flow.get('gewaehlteSchale') || PRODUKT;
const teilGewaehlt = GEWAEHLT !== PRODUKT;
const BAUTEIL = teilGewaehlt
              ? GEWAEHLT
              : (env.get('SDI_LCA_MACHINE_PART') || 'Bolzen_Aluminium');

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

// Round the shells in turn, not just two.
//
// The poll used to alternate between the product and one configured part.
// On the product it then said "2 machines, checked on Bolzen" - as though
// that were the whole of production. Three parts had been measured. Whoever
// reads the row wants to know how much of the assembled product is backed
// by measurement, not what happens to sit in one arbitrarily picked shell.
//
// With a part selected the alternation between product and that part
// stands: only that one counts then.
const bauteile = flow.get('bauteile') || [];
const runde = teilGewaehlt
    ? [PRODUKT, GEWAEHLT]
    : [PRODUKT].concat(bauteile.length ? bauteile : [BAUTEIL]);

const schritt = (flow.get('standSchritt') || 0) % runde.length;
const schale = runde[schritt];
flow.set('standSchale', schale);
flow.set('standIstProdukt', schritt === 0);
flow.set('standRunde', runde.length);
// Pass the list itself along: the evaluation runs in another function and
// would otherwise not know it.
flow.set('standListe', runde);
flow.set('standSchritt', (schritt + 1) % runde.length);

// The nameplate first: it holds the article number of this shell.
//
// It used to be a table in the source code - part name to number. Right for
// the demonstrator, wrong for every other product. It is kept in the
// nameplate, and that is where it belongs read from.
msg.url = AAS + '/submodels/' + b64(BASIS + '/' + schale + '/Nameplate');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Holds on to the article number of the shell and then reads the data
// sources.
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';
const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const schale = flow.get('standSchale');

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const sm = msg.payload;
let nummer = '';
if (sm && Array.isArray(sm.submodelElements)) {
    const e = sm.submodelElements.find(function (x) {
        return x.idShort === 'ProductArticleNumberOfManufacturer';
    });
    nummer = e ? String(e.value || '') : '';
}
const tabelle = flow.get('artikelNachSchale') || {};
if (nummer) { tabelle[schale] = nummer; }
flow.set('artikelNachSchale', tabelle);

msg.url = AAS + '/submodels/' + b64(BASIS + '/' + schale + '/DataSources');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Records what each source delivered.
//
// Every shell answers only for what it is responsible. The product does
// carry a MachineData container as well, but an empty one - measuring
// happens on the parts. Evaluating it too would have every second poll wipe
// out the good entry again.
const schale = flow.get('standSchale');
const istProdukt = flow.get('standIstProdukt');
const sm = msg.payload;

function finde(sammlung, name) {
    return ((sammlung || {}).value || []).find(e => e && e.idShort === name);
}
function wert(sammlung, name) {
    const e = finde(sammlung, name);
    return e ? e.value : null;
}

let liste = null;
for (const e of (sm && sm.submodelElements) || []) {
    if (e.idShort === 'DataSources') { liste = e; }
}
function quelle(namen) {
    for (const n of namen) {
        const g = finde(liste, n);
        if (g) { return g; }
    }
    return null;
}

const stand = flow.get('quellenstand') || {};
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const GEWAEHLT = flow.get('gewaehlteSchale') || PRODUKT;
const teilGewaehlt = GEWAEHLT !== PRODUKT;

// Every row records which shell it came from and whether it concerns the
// selected part at all.
//
// With a part selected, ERP and simulation were still read from the product
// shell and stood there green - as though the screw had an assembly
// simulation. It has none: assembly concerns the product. Green means
// "present for what is selected"; what only holds product-wide has to say
// so, otherwise one reads someone else's figures as one's own.
// The collection is tidied, not emptied.
//
// Emptying was wrong: the round goes shell by shell, one per tick. After
// emptying, the machine table showed only what had been gathered since -
// two machines one moment, four the next. It is replaced per shell anyway;
// only what no longer exists is thrown out here.
if (istProdukt && !teilGewaehlt) {
    const gueltig = (flow.get('standListe') || []).slice(1);
    flow.set('maschSammlung', (flow.get('maschSammlung') || [])
        .filter(function (e) { return gueltig.indexOf(e.schale) >= 0; }));
    flow.set('maschLaeufe', (flow.get('maschLaeufe') || [])
        .filter(function (e) { return gueltig.indexOf(e.schale) >= 0; }));
}

function merke(name, eintrag, produktweit) {
    eintrag.schale = schale;
    eintrag.produktweit = !!(produktweit && teilGewaehlt);
    stand[name] = eintrag;
}
// The same format as in the machine table. Two spellings of the same thing
// read as two different statements.
const jetzt = new Date(Date.now() - new Date().getTimezoneOffset() * 60000)
    .toISOString().replace('T', ' ').slice(0, 16);

// The moment the data came into being - not the moment we looked. Only that
// makes it possible to tell whether a result is older than the data it is
// supposed to rest on.
function juengster(sammlung, felder) {
    let neuster = null;
    for (const f of felder) {
        const w = wert(sammlung, f);
        if (w && (!neuster || String(w) > String(neuster))) { neuster = w; }
    }
    return neuster;
}
function merkeDatum(schluessel, datum) {
    if (!datum) { return; }
    const alle = flow.get('datenStand') || {};
    alle[schluessel] = datum;
    flow.set('datenStand', alle);
}

if (istProdukt) {
    // The part names of the interface come from the bill of material. The
    // idShort of a shell is formed from the part name by the same rule as
    // in the rest of the KIT.
    function alsKurzname(text) {
        return String(text || '')
            .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
            .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue')
            .replace(/ß/g, 'ss')
            .replace(/[^A-Za-z0-9_]/g, '_').replace(/__+/g, '_')
            .replace(/_+$/, '');
    }
    for (const name of ['ERP', 'ERPData', 'PLM', 'EngineeringData_PLM']) {
        const q = finde(liste, name);
        const stueckliste = q ? finde(q, 'BillOfMaterial') : null;
        const positionen = ((stueckliste || {}).value) || [];
        if (positionen.length) {
            flow.set('bauteile', positionen
                .map(p => alsKurzname(wert(p, 'ComponentName')))
                .filter(Boolean));
            break;
        }
    }

    // With a part selected, PLM comes from the part shell - the screw weighs
    // 1 g, not the 15 g of the whole pen. So only here when the assembled
    // product itself is selected.
    const plm = teilGewaehlt
        ? null : quelle(['PLM', 'EngineeringData_PLM', 'Engineering Data / PLM']);
    if (plm) {
        const gewicht = wert(plm, 'Weight');
        const werkstoff = wert(plm, 'Material');
        const stueckliste = finde(plm, 'BillOfMaterial');
        const positionen = ((stueckliste || {}).value || []).length;
        stand.plm = {
            text: (gewicht ? gewicht + ' kg' : 'no weight')
                + (werkstoff ? ', ' + werkstoff : '')
                + (positionen ? ', ' + positionen + ' positions' : ''),
            gut: !!gewicht, geprueft: true, zeit: jetzt };
        stand.plm.schale = schale;
        merkeDatum('plm', juengster(plm, ['TimeOfRetrieval']));
    }

    const erp = quelle(['ERP', 'ERPData']);
    if (erp) {
        const stueckliste = finde(erp, 'BillOfMaterial');
        const auftrag = finde(erp, 'ManufacturingOrder');
        const anzahl = ((stueckliste || {}).value || []).length;
        const menge = auftrag ? wert(auftrag, 'OrderQuantity') : null;
        stand.erp = { text: anzahl + ' positions'
                          + (menge ? ', order over ' + menge + ' pieces' : ''),
                      gut: anzahl > 0, geprueft: true, zeit: jetzt,
                      schale: schale, produktweit: teilGewaehlt };

        // The booked assembly: which piece was put together from which
        // pieces. That is the difference between a statement and evidence -
        // and it is only there when it was booked.
        //
        // Every booked piece, the most recent first, so that the dropdown
        // above shows what just came off the line.
        const sammlung = finde(erp, 'AssemblyRecords');
        const einzeln = finde(erp, 'AssemblyRecord');
        const roh = sammlung ? (sammlung.value || [])
                  : (einzeln ? [einzeln] : []);
        const montagen = roh.map(function (m) {
            const teile = ((finde(m, 'InstalledComponents') || {}).value) || [];
            return {
                auftrag: wert(m, 'ManufacturingOrder') || '',
                stueck: wert(m, 'SerialNumber') || '',
                zeit: wert(m, 'TimeOfBooking') || '',
                teile: teile.map(function (k) {
                    return { artikel: wert(k, 'ArticleNumber') || '',
                             nummer: wert(k, 'SerialNumber') || '' };
                })
            };
        }).filter(function (m) { return m.stueck; })
          .sort(function (a, b) { return String(b.zeit).localeCompare(String(a.zeit)); });
        flow.set('montagen', montagen);

        // The selected instance, or the most recent one while none is chosen.
        const gewaehlt = flow.get('gewaehlteInstanz');
        const treffer = montagen.find(function (m) { return m.stueck === gewaehlt; });
        flow.set('montage', treffer || montagen[0] || null);
        merkeDatum('erp', juengster(erp, ['TimeOfRetrieval']));
    }

    const sim = quelle(['Simulation']);
    if (sim) {
        const gaenge = ((finde(sim, 'SimulationProcesses') || {}).value) || [];
        const summe = gaenge.reduce((s, g) => {
            const w = parseFloat(wert(g, 'EnergyPerUnit'));
            return isNaN(w) ? s : s + w;
        }, 0);
        stand.simulation = { text: gaenge.length + ' operations, '
                                 + summe.toFixed(4) + ' MJ',
                             gut: gaenge.length > 0, geprueft: true,
                             zeit: jetzt, schale: schale,
                             produktweit: teilGewaehlt };
        merkeDatum('simulation', juengster(sim, ['TimeOfRetrieval']));
    }
} else {
    // The PLM entry of the part - weight and material of this one part.
    if (teilGewaehlt) {
        const teilPlm = quelle(['PLM', 'EngineeringData_PLM',
                                'Engineering Data / PLM']);
        if (teilPlm) {
            const g = wert(teilPlm, 'Weight');
            const w = wert(teilPlm, 'Material');
            stand.plm = {
                text: (g ? g + ' kg' : 'no weight') + (w ? ', ' + w : ''),
                gut: !!g, geprueft: true, zeit: jetzt, schale: schale };
            merkeDatum('plm', juengster(teilPlm, ['TimeOfRetrieval']));
        }
    }

    const maschinen = quelle(['MachineData', 'Manufacturing']);
    if (maschinen) {
        const prozesse = ((finde(maschinen, 'ManufacturingProcesses') || {}).value) || [];
        const summe = prozesse.reduce((s, p) => {
            const w = parseFloat(wert(p, 'EnergyPerUnit'));
            return isNaN(w) ? s : s + w;
        }, 0);
        if (teilGewaehlt) {
            stand.maschinen = {
                text: prozesse.length
                    ? prozesse.length + ' machine(s), ' + summe.toFixed(4) + ' MJ'
                    : 'nothing measured on ' + schale.replace(/_/g, ' '),
                gut: prozesse.length > 0, geprueft: true, zeit: jetzt,
                schale: schale };
        } else {
            // Gather across every part. Only "how many parts were measured"
            // says how far production is backed by evidence - a single shell
            // picked out at random does not answer that.
            const sammlung = flow.get('maschSammlung') || [];
            const schon = sammlung.findIndex(e => e.schale === schale);
            const eintrag = { schale: schale, anzahl: prozesse.length,
                              energie: summe };
            if (schon >= 0) { sammlung[schon] = eintrag; } else { sammlung.push(eintrag); }
            flow.set('maschSammlung', sammlung);
            const gemessen = sammlung.filter(e => e.anzahl > 0);
            const gesamt = gemessen.reduce((s, e) => s + e.energie, 0);
            const teile = (flow.get('bauteile') || []).length || sammlung.length;
            stand.maschinen = {
                text: gemessen.length
                    ? gemessen.length + ' of ' + teile + ' parts measured, '
                      + gesamt.toFixed(4) + ' MJ total: '
                      + gemessen.map(e => e.schale.replace(/_/g, ' ')).join(', ')
                    : 'nothing measured on any part yet',
                gut: gemessen.length > 0, geprueft: sammlung.length >= teile,
                zeit: jetzt };
        }
        // Take the runs themselves along. The machine table shows them and
        // needs the part shell for that - the OPC UA submodel holds the raw
        // recording without a serial number. Two sources for the same table
        // would be two states that drift apart.
        const laeufe = flow.get('maschLaeufe') || [];
        const ohneDiese = laeufe.filter(function (l) { return l.schale !== schale; });
        for (const pr of prozesse) {
            ohneDiese.push({
                schale: schale,
                maschine: pr.idShort,
                leistung: parseFloat(wert(pr, 'AveragePower')),
                dauer: parseFloat(wert(pr, 'ProcessDuration')),
                stueck: parseFloat(wert(pr, 'PieceCount')) || 1,
                energie: parseFloat(wert(pr, 'EnergyPerUnit')),
                ende: wert(pr, 'TimeManufacturingEnd')
                   || wert(maschinen, 'TimeManufacturingEnd') || '',
                serie: wert(pr, 'SerialNumbers') || '',
                auftrag: wert(pr, 'ManufacturingOrder') || '',
                verteilung: wert(pr, 'EnergyAllocation') || ''
            });
        }
        flow.set('maschLaeufe', ohneDiese);

        let neuste = juengster(maschinen, ['TimeOfRetrieval']);
        for (const p of prozesse) {
            const e = juengster(p, ['TimeManufacturingEnd']);
            if (e && (!neuste || String(e) > String(neuste))) { neuste = e; }
        }
        merkeDatum('maschinen', neuste);
    } else {
        // No machine-data entry at all in this shell. That too is a complete
        // answer and not an open question - nothing is manufactured on a
        // purchased part.
        if (teilGewaehlt) {
            stand.maschinen = {
                text: 'no machine data in ' + schale.replace(/_/g, ' ')
                    + ' - nothing is manufactured on a purchased part',
                gut: false, geprueft: true, zeit: jetzt, schale: schale };
        }
    }
}

flow.set('quellenstand', stand);
msg.payload = stand;
return msg;

// Shows, per source, what the shell holds.
const stand = msg.payload || {};
const QUELLEN = [
    ['plm', 'PLM', 'weight, material, bill of material'],
    ['erp', 'ERP', 'quantities and order'],
    ['simulation', 'Simulation', 'assembly energy'],
    ['maschinen', 'MachineData', 'measured production energy'],
];

let zeilen = '';
for (const q of QUELLEN) {
    const d = stand[q[0]];
    // Four states, not two: not looked at yet (grey), present (green),
    // looked at and empty (red) - and blue for what only holds product-wide.
    // One yellow dot for both of the first two left it open whether
    // something was still coming; and without the fourth, the assembly
    // simulation stood green under a screw that nothing is assembled on.
    const punkt = !d ? 'sdi-punkt-leer'
                : (d.produktweit ? 'sdi-punkt-produkt'
                : (d.gut ? 'sdi-punkt-gut'
                         : (d.geprueft ? 'sdi-punkt-fehlt' : 'sdi-punkt-warten')));
    zeilen += '<tr>'
        + '<td><span class="sdi-punkt ' + punkt + '"></span>'
        + '<span class="sdi-name">' + q[1] + '</span>'
        + '<div class="sdi-leise">' + q[2] + '</div></td>'
        + '<td>' + (d ? d.text : 'nothing in the shell')
        // Where the row came from. Without it one reads the figures of the
        // assembled product as those of the selected part.
        + (d && d.schale
            ? '<div class="sdi-leise">' + (d.produktweit
                ? 'product level, from ' + d.schale.replace(/_/g, ' ')
                  + ' &mdash; not part of this part'
                : 'from ' + d.schale.replace(/_/g, ' ')) + '</div>'
            : '')
        + '</td>'
        + '<td class="sdi-rechts sdi-leise">' + (d ? d.zeit : '') + '</td></tr>';
}

msg.payload = '<div class="sdi"><div class="sdi-titel">Data sources</div>'
    + '<table class="sdi-tabelle"><tbody>' + zeilen + '</tbody></table></div>';
return msg;

// Clears an error message once everything runs again.
//
// A message left standing is worse than none: it asserts a state that no
// longer exists.
const letzter = flow.get('letzterFehler') || 0;
const abgeraeumt = flow.get('fehlerAbgeraeumt') || 0;

if (!letzter) {
    if (abgeraeumt) { return null; }
    flow.set('fehlerAbgeraeumt', Date.now());
    msg.payload = '<div class="sdi"><div class="sdi-hinweis sdi-hinweis-ruhe">'
        + 'Everything running.</div></div>';
    return msg;
}
if (abgeraeumt >= letzter) { return null; }
if (Date.now() - letzter < 30000) { return null; }
flow.set('fehlerAbgeraeumt', letzter);
msg.payload = '<div class="sdi"><div class="sdi-hinweis sdi-hinweis-ruhe">'
    + 'Everything running again since '
    + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    + '.</div></div>';
return msg;

// Shows the production runs per machine.
//
// Read from the part shells, not from the OPC UA submodel. That holds the
// raw recording - without a serial number and without an order. A table
// from two sources would be two states that drift apart; and the statement
// that matters only comes into being in the shell: this run belongs to this
// piece.
//
// The value per piece follows from power times duration over the number of
// pieces. It is not held in the shell, because it changes as soon as one of
// those three is corrected - it is computed where it is needed.
const alleLaeufe = flow.get('maschLaeufe') || [];

// Narrow down to the selected piece.
//
// A product passport answers "what is inside this pen", not "what have we
// ever measured". If a run belongs to a part installed in this piece, it
// belongs here; otherwise not. Without a booked assembly all runs stand,
// and the page says so.
//
// The filter goes by the selected number. For the assembled product those
// are the numbers of its parts, for a part its own.
const gewaehlteNummer = flow.get('gewaehlteInstanz') || '';
const montagen = flow.get('montagen') || [];
const alsErzeugnis = montagen.find(function (m) { return m.stueck === gewaehlteNummer; });
const nummern = alsErzeugnis
    ? (alsErzeugnis.teile || []).map(function (k) { return k.nummer; })
    : (gewaehlteNummer ? [gewaehlteNummer] : []);
const montage = alsErzeugnis || (gewaehlteNummer ? { stueck: gewaehlteNummer } : null);
const laeufe = nummern.length
    ? alleLaeufe.filter(function (l) { return nummern.indexOf(l.serie) >= 0; })
    : alleLaeufe;

let zeilen = '';
for (const l of laeufe) {
    const leistung = l.leistung;
    const dauer = l.dauer;
    const stueck = l.stueck || 1;
    if (isNaN(leistung) || isNaN(dauer)) { continue; }
    const energie = isNaN(l.energie) ? (leistung * dauer / 1e6 / stueck) : l.energie;
    zeilen += '<tr>'
        + '<td><span class="sdi-name">' + l.maschine.replace(/_/g, ' ') + '</span>'
        + '<div class="sdi-leise">into ' + l.schale.replace(/_/g, ' ') + '</div>'
        + '<div class="sdi-leise">' + (l.ende
            ? String(l.ende).replace('T', ' ').slice(0, 16) : 'no time recorded')
        + (l.auftrag ? ' &middot; ' + l.auftrag : '') + '</div>'
        + (l.serie
            ? '<div class="sdi-leise">piece <code>' + l.serie + '</code></div>'
            : '<div class="sdi-leise">no serial number</div>')
        + '</td>'
        + '<td class="sdi-rechts">' + leistung.toFixed(0) + ' W</td>'
        + '<td class="sdi-rechts">' + dauer.toFixed(0) + ' s</td>'
        + '<td class="sdi-rechts sdi-leise">' + stueck.toFixed(0) + '</td>'
        + '<td class="sdi-rechts"><strong>' + energie.toFixed(4) + '</strong> MJ'
        + (String(l.verteilung || '').indexOf('average') === 0
            ? '<div class="sdi-leise">average over the run</div>' : '')
        + '</td></tr>';
}

if (!zeilen) {
    zeilen = '<tr><td colspan="5" class="sdi-leise">No measurements yet. '
           + 'Record one with record_opcua.py.</td></tr>';
}

msg.payload = '<div class="sdi"><div class="sdi-titel">Machine measurements</div>'
    + '<div class="sdi-leise" style="margin:-6px 0 12px">'
    + (nummern.length
        ? 'The runs that produced the parts installed in <code>'
          + montage.stueck + '</code>. ' + laeufe.length + ' of '
          + alleLaeufe.length + ' recorded runs belong to this piece.'
        : 'Every recorded run. Book an assembly to see the runs of one piece.')
    + '</div>'
    + '<table class="sdi-tabelle"><thead><tr><th>Machine</th>'
    + '<th class="sdi-rechts">Power</th><th class="sdi-rechts">Duration</th>'
    + '<th class="sdi-rechts">Pieces</th><th class="sdi-rechts">Per piece</th>'
    + '</tr></thead><tbody>' + zeilen + '</tbody></table></div>';
return msg;

// Reads the results of every shell in turn from the ILCD submodel.
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';
const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const PRODUKT = flow.get('gewaehlteSchale')
             || env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
// The parts are held in the bill of material of the product - a list of
// names in the configuration would be a second place for the same truth and
// would have to be changed for every other product.
const BAUTEILE = (flow.get('bauteile') || []).filter(s => s && s !== PRODUKT);

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const reihe = [PRODUKT].concat(BAUTEILE);
let index = flow.get('ergebnisIndex') || 0;

// Two passes at the same time append their results to one another - the
// parts then stand twice in the table with the product in between. A new
// start is therefore refused while one is running; only when that one has
// hung is it replaced, after a minute.
if (msg.topic === 'start') {
    const laeuft = flow.get('ergLaeuft') || 0;
    if (laeuft && Date.now() - laeuft < 60000) { return [null, null]; }
    flow.set('ergLaeuft', Date.now());
    index = 0;
    flow.set('ergebnisse', []);
}

if (index >= reihe.length) {
    flow.set('ergebnisIndex', 0);
    flow.set('ergLaeuft', 0);
    msg.payload = flow.get('ergebnisse') || [];
    return [null, msg];
}

flow.set('ergebnisSchale', reihe[index]);
flow.set('ergebnisIndex', index + 1);
msg.url = AAS + '/submodels/' + b64(BASIS + '/' + reihe[index] + '/ILCD');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
msg.topic = '';
return [msg, null];

// Evaluates one ILCD: climate value, sources, every category.
const schale = flow.get('ergebnisSchale');
const sm = msg.payload;
const gesammelt = flow.get('ergebnisse') || [];

function wert(sammlung, name) {
    const e = ((sammlung || {}).value || []).find(x => x && x.idShort === name);
    return e ? e.value : null;
}

const behaelter = ((sm && sm.submodelElements) || [{}])[0];
const laeufe = [];
for (const it of (behaelter.value || [])) {
    const methoden = ((it.value || [])
        .find(x => x && x.idShort === 'LCIAMethods') || {}).value || [];
    // One list per method. All categories used to go into a single pot - in
    // a shell calculated with four methods in turn it then read "All 82
    // impact categories" under the name of one of them. Four methods side by
    // side are four results, not one with four times as many rows.
    const bloecke = [];
    for (const m of methoden) {
        const liste = [];
        let kl = null, eh = '';
        for (const k of (m.value || [])) {
            const w = parseFloat(wert(k, 'Value'));
            if (isNaN(w)) { continue; }
            liste.push({ name: k.idShort, wert: w, einheit: wert(k, 'Unit') });
            // Exactly that category, not merely one starting with Climate:
            // Climate_change_Land_use is zero and would make a correct
            // result look empty.
            if (k.idShort === 'Climate_change') { kl = w; eh = wert(k, 'Unit') || ''; }
        }
        if (liste.length) {
            bloecke.push({ name: m.idShort || '', kategorien: liste,
                           klima: kl, einheit: eh });
        }
    }

    // The method selected above is shown. If this shell has not been
    // calculated with it yet, the last one that has a climate value - and
    // failing that, simply the last one.
    const gewaehlteMethode = String((global.get('selectedMethodNames') || [])[0] || '')
        .replace(/[^A-Za-z0-9]/g, '').toLowerCase();
    function passt(b) {
        return b.name.replace(/[^A-Za-z0-9]/g, '').toLowerCase() === gewaehlteMethode;
    }
    const block = bloecke.find(passt)
               || bloecke.slice().reverse().find(b => b.klima !== null)
               || bloecke[bloecke.length - 1];
    if (!block) { continue; }
    const klima = block.klima;
    const einheit = block.einheit;
    const methodenname = block.name;
    const kategorien = block.kategorien;
    // A run without a climate category is taken in regardless. It used to
    // fall out, and the interface reported "nothing calculated yet" although
    // a complete result stood in the shell - it had simply been calculated
    // with a method that knows no climate value. A display that keeps quiet
    // about results that are there is worse than an empty one.
    if (!kategorien.length) { continue; }
    laeufe.push({
        name: it.idShort, quellen: wert(it, 'DataSource') || '',
        zeit: wert(it, 'TimeOfLCA') || '', klima: klima, einheit: einheit,
        methode: methodenname, kategorien: kategorien,
        menge: wert(it, 'TargetOutput') || '', gewicht: wert(it, 'WeightOfPart') || ''
    });
}

// A shell appears exactly once in the list. Earlier versions appended - if
// two passes then ran shortly after one another, every part stood twice in
// the table with the product in between. Replacing instead of appending
// makes that impossible, however often the page is refreshed.
const stelle = gesammelt.findIndex(e => e && e.schale === schale);
if (stelle >= 0) { gesammelt[stelle] = { schale: schale, laeufe: laeufe }; }
else { gesammelt.push({ schale: schale, laeufe: laeufe }); }
flow.set('ergebnisse', gesammelt);
msg.payload = '';
return msg;

// Baut die Ergebnisansicht: Bauteile, Kategorien, Vergleich, Verlauf.
const alle = msg.payload || [];
const leer = '<div class="sdi"><div class="sdi-titel">Result</div>'
    + '<div class="sdi-hinweis sdi-hinweis-ruhe">Nothing calculated yet. '
    + 'Press <strong>Calculate</strong> above.</div></div>';
if (!alle.length) { msg.payload = leer; return msg; }

const produkt = alle[0];
const letzter = (produkt.laeufe || []).slice(-1)[0];
if (!letzter) { msg.payload = leer; return msg; }

// Only an assembled product can be broken down. With a single part selected
// above, the part list of the product beside it makes no sense: the shares
// were computed against the value of the part and came out at 1872 %, while
// the assembly energy went negative. A figure that is obviously nonsense
// damages trust in every other figure on the page.
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
const istProdukt = produkt.schale === PRODUKT;

function zahl(x, n) {
    return (x === null || x === undefined || isNaN(x))
        ? '—' : Number(x).toFixed(n === undefined ? 6 : n);
}

// Without a climate value there are no shares to show - any calculation
// with it would give NaN. The categories of the method stand further down
// and are the result in that case.
const ohneKlima = (letzter.klima === null || letzter.klima === undefined)
               || !istProdukt;

// --- Bauteile mit Anteilsbalken -----------------------------------------
let summe = 0;
let zeilen = '';
for (const eintrag of (ohneKlima ? [] : alle.slice(1))) {
    const lauf = (eintrag.laeufe || []).slice(-1)[0];
    if (!lauf || lauf.klima === null || lauf.klima === undefined) { continue; }
    summe += lauf.klima;
    const anteil = 100 * lauf.klima / letzter.klima;
    const gemessen = /MachineData|Manufacturing/.test(lauf.quellen);
    // "material only" read like "measurement still missing". Purchased parts
    // are not manufactured here - there is no manufacturing energy of their
    // own, and that is not a shortcoming but the state of affairs.
    //
    // Purchased means what we do not manufacture ourselves - and that is
    // already held in the setting that also tells Odoo which articles get a
    // serial number. A second list in the source would be a second truth
    // that drifts apart with the first product that changes.
    const SELBST = String(env.get('SDI_SERIAL_ARTICLES') || '')
        .split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    const artikelTabelle = flow.get('artikelNachSchale') || {};
    const artikelNr = artikelTabelle[eintrag.schale] || '';
    const zugekauft = SELBST.length && artikelNr
        ? SELBST.indexOf(artikelNr) < 0 : false;
    const herkunft = gemessen ? 'production energy measured'
        : (zugekauft ? 'purchased part, material only' : 'material only');
    // The way from the figure to where it came from. Without it the figure
    // has to be believed rather than checked - and being checkable is what
    // the shell is for.
    const UI = env.get('SDI_AAS_UI_URL') || 'http://localhost:3001';
    const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
    const verweis = UI + '/?aas=' + encodeURIComponent(BASIS + '/' + eintrag.schale);
    zeilen += '<tr>'
        + '<td><a class="sdi-name sdi-verweis" href="' + verweis
        + '" target="_blank" rel="noopener">' + eintrag.schale.replace(/_/g, ' ')
        + '</a><div class="sdi-leise">' + herkunft + '</div></td>'
        + '<td class="sdi-rechts">' + zahl(lauf.klima) + '</td>'
        + '<td style="width:120px"><div class="sdi-balken"><div style="width:'
        + Math.max(2, Math.min(100, anteil)).toFixed(0) + '%"></div></div></td>'
        + '<td class="sdi-rechts sdi-leise">' + anteil.toFixed(1) + ' %</td></tr>';
}

// If a source was written after the calculation, the result is out of date -
// and nothing about it shows that. This exact case cost us time while
// building the chain: the display was consistent, just no longer with the
// data.
const datenStand = flow.get('datenStand') || {};
let neuer = [];
for (const schluessel of Object.keys(datenStand)) {
    if (letzter.zeit && String(datenStand[schluessel]) > String(letzter.zeit)) {
        neuer.push(schluessel);
    }
}

let html = '<div class="sdi"><div class="sdi-titel">Result</div>';
if (neuer.length) {
    html += '<div class="sdi-hinweis sdi-hinweis-lauf" style="margin-bottom:16px">'
        + '<span class="sdi-punkt sdi-punkt-warten" style="margin-top:6px"></span>'
        + '<span><strong>The result is older than the data.</strong> '
        + neuer.join(', ') + ' changed after the last calculation. '
        + 'Press <strong>Calculate</strong> to bring it up to date.</span></div>';
}
if (!istProdukt) {
    html += '<div class="sdi-hinweis sdi-hinweis-ruhe">'
        + '<span><strong>' + produkt.schale.replace(/_/g, ' ')
        + '</strong> is a single part, so there is nothing to split. '
        + (letzter.klima === null || letzter.klima === undefined
            ? 'The chosen method has no Climate change category. '
            : 'Its footprint is <strong>' + zahl(letzter.klima) + ' '
              + (letzter.einheit || '') + '</strong>. ')
        + 'Choose the product above to see the split by part.'
        + '</span></div>';
} else if (ohneKlima) {
    html += '<div class="sdi-hinweis sdi-hinweis-ruhe">'
        + '<span>Calculated with <strong>' + (letzter.methode || 'the chosen method')
        + '</strong>, which has no Climate change category, so there is no '
        + 'carbon footprint and no split by part. Its '
        + (letzter.kategorien || []).length + ' categories are listed below.'
        + '</span></div>';
}
html += ohneKlima ? '' : ''
    + '<table class="sdi-tabelle"><thead><tr><th>Part</th>'
    + '<th class="sdi-rechts">' + (letzter.einheit || '') + '</th>'
    // "Share" belongs over its figures as well. The bar beside it is
    // decoration; what is read is the percentage at the right edge.
    + '<th colspan="2" class="sdi-rechts">Share</th></tr></thead><tbody>' + zeilen + '</tbody>'
    + '<tfoot><tr><td class="sdi-name">Sum of the parts</td>'
    + '<td class="sdi-rechts sdi-name">' + zahl(summe) + '</td>'
    + '<td colspan="2" class="sdi-leise">assembly energy adds '
    + zahl(letzter.klima - summe) + '</td></tr></tfoot></table>'
    + '<div class="sdi-leise" style="margin-top:8px">Every part name links to '
    + 'its administration shell, where the input data behind the number can be '
    + 'checked.</div>';

// --- Comparison with the previous run ------------------------------------
let vorher = (produkt.laeufe || []).length > 1
    ? produkt.laeufe[produkt.laeufe.length - 2] : null;
const gemerkt = flow.get('letztesErgebnis');
if (!vorher && gemerkt && gemerkt.zeit !== letzter.zeit) { vorher = gemerkt; }
if (letzter.zeit !== (gemerkt || {}).zeit) { flow.set('letztesErgebnis', letzter); }

if (vorher && !ohneKlima && vorher.klima !== null && vorher.klima !== undefined) {
    const unterschied = letzter.klima - vorher.klima;
    const klasse = unterschied > 0 ? 'sdi-mehr' : (unterschied < 0 ? 'sdi-weniger' : '');
    const zeichen = unterschied > 0 ? '+' : '';
    html += '<div class="sdi-vergleich"><strong>Compared with the run before</strong><br>'
        + zahl(vorher.klima) + '<span class="sdi-pfeil">&rarr;</span>'
        + zahl(letzter.klima) + ' <span class="' + klasse + '">'
        + zeichen + zahl(unterschied) + '</span>'
        + (vorher.klima ? ' <span class="sdi-leise">(' + zeichen
            + (100 * unterschied / vorher.klima).toFixed(1) + ' %)</span>' : '')
        + '<div class="sdi-leise" style="margin-top:4px">before: '
        + (vorher.quellen || '—') + '<br>now: ' + (letzter.quellen || '—')
        + '</div></div>';
}

// --- Alle Wirkungskategorien, aufklappbar --------------------------------
const kategorien = letzter.kategorien || [];
if (kategorien.length) {
    let katzeilen = '';
    for (const k of kategorien) {
        katzeilen += '<tr><td>' + k.name.replace(/_/g, ' ') + '</td>'
            + '<td class="sdi-rechts">' + Number(k.wert).toPrecision(6) + '</td>'
            + '<td class="sdi-leise">' + (k.einheit || '') + '</td></tr>';
    }
    html += '<details><summary>All ' + kategorien.length
        + ' impact categories of ' + (letzter.methode || 'the method') + '</summary>'
        + '<table class="sdi-tabelle"><tbody>' + katzeilen
        + '</tbody></table></details>';
}

// --- History of the runs -------------------------------------------------
if ((produkt.laeufe || []).length > 1) {
    let verlauf = '';
    for (const l of produkt.laeufe) {
        verlauf += '<tr><td class="sdi-leise">'
            + String(l.zeit).replace('T', ' ').slice(0, 16) + '</td>'
            + '<td class="sdi-rechts">' + zahl(l.klima) + '</td>'
            + '<td class="sdi-leise">' + (l.quellen || '') + '</td></tr>';
    }
    html += '<details><summary>History of ' + produkt.laeufe.length
        + ' runs in this shell</summary><table class="sdi-tabelle"><tbody>'
        + verlauf + '</tbody></table></details>';
}

msg.payload = html + '</div>';
return msg;

// Builds the headline area: result, origin, state of the sources.
const daten = flow.get('ergebnisse') || [];
const stand = flow.get('quellenstand') || {};
// The name comes from the dropdown; before anything is picked it sits in
// global context, which the calculation flow reads anyway.
const gewaehlt = global.get('dashboardShell') || '';
const schale = flow.get('gewaehlteSchale')
            || gewaehlt.split('/').pop()
            || env.get('SDI_LCA_PRODUCT') || '—';
const STIL = flow.get('stil') || '';

// The same precision as in the result table. Two different roundings of the
// same quantity on one page read as two different values.
function zahl(x, n) {
    return (x === null || x === undefined || isNaN(x))
        ? '—' : Number(x).toFixed(n === undefined ? 6 : n);
}

const produkt = daten[0];
const lauf = produkt ? (produkt.laeufe || []).slice(-1)[0] : null;

// A figure without a reference quantity cannot be quoted. Quantity and
// weight are in the result (TargetOutput, WeightOfPart) - they belong next
// to the figure, not in a submodel that has to be unfolded first.
const bezug = [];
// Older shells hold the quantity in German ("1 Stueck"). The shell is left
// as it is - the translation happens for the display only. Shells written
// by the current flow already say "piece(s)", and then this does nothing.
if (lauf && lauf.menge) {
    // Older shells hold the quantity in German ("1 Stueck"). The shell is
    // left as it is - the translation happens for the display only.
    bezug.push('per ' + String(lauf.menge).split('Stueck').join('piece'));
}
if (lauf && lauf.gewicht) { bezug.push(lauf.gewicht + ' kg'); }
bezug.push('cradle-to-gate');

const QUELLEN = [['plm', 'PLM'], ['erp', 'ERP'],
                 ['simulation', 'Simulation'], ['maschinen', 'MachineData']];
let chips = '';
for (const q of QUELLEN) {
    const d = stand[q[0]];
    const an = d && d.gut;
    chips += '<span class="sdi-chip' + (an ? ' sdi-chip-an' : '') + '">'
           + q[1] + '</span>';
}

// One sentence on what the page is - and behind it, unfoldable, the longer
// explanation. Help has to remain findable later, when the question
// actually comes up; a text that appears only on the first visit is gone
// exactly when it is needed.
//
// Which piece does this shell describe? Without a number the footprint
// stays a statement about a type. With it there - and with what the piece
// was built from - it becomes evidence.
const montage = flow.get('montage');

let html = STIL + '<div class="sdi">'
    // The full name spelled out once. The navigation carries the short form
    // - there is room for two words there, not five - but here someone
    // seeing the page for the first time has to be able to read what it is
    // about.
    + '<div class="sdi-marke">Sustainability Data Integration KIT'
    + '<span>SDI-KIT</span></div>'
    + '<div class="sdi-einleitung">Product carbon footprint, taken from the '
    + 'digital twin: engineering data, ERP quantities, simulated assembly '
    + 'and measured machine energy.'
    + '<details class="sdi-hilfe"><summary>How this works</summary>'
    + '<p>Each part of the pen has an administration shell. Four sources '
    + 'write into those shells: <strong>PLM</strong> the geometry, material '
    + 'and bill of material, <strong>ERP</strong> the order quantities, '
    + '<strong>Simulation</strong> the assembly energy, and '
    + '<strong>MachineData</strong> the energy actually measured at the '
    + 'lathe, mill and 3D printer.</p>'
    + '<p>A run collects those four, hands the figures to openLCA and writes '
    + 'the result back into the shell &mdash; per part and for the product. '
    + 'The chips above show which sources are present; a run stops rather '
    + 'than calculating on missing data.</p>'
    + '<p>Everything here can also be done from the command line, without '
    + 'this dashboard. The scripts are in the src folder.</p>'
    + '</details></div>';
if (lauf && (lauf.klima === null || lauf.klima === undefined)) {
    // Calculated, but the method knows no climate value. That belongs said
    // rather than kept quiet - together with the way to put it right.
    html += '<div class="sdi-zahl" style="font-size:30px">'
          + (lauf.kategorien || []).length + ' categories'
          + '<span class="sdi-einheit">no climate value</span></div>'
          + '<div class="sdi-unterzeile">' + schale.replace(/_/g, ' ')
          + ' &middot; calculated ' + String(lauf.zeit).replace('T', ' ').slice(0, 16)
          + ' with ' + String(lauf.methode || 'an unknown method').replace(/_/g, ' ')
          + ', which has no Climate change category. Pick a method that has '
          + 'one to get a carbon footprint.</div>';
} else if (lauf) {
    html += '<div class="sdi-zahl">' + zahl(lauf.klima)
          + '<span class="sdi-einheit">' + (lauf.einheit || '') + '</span></div>'
          + '<div class="sdi-bezug">' + bezug.join(' &middot; ') + '</div>'
          + '<div class="sdi-unterzeile">' + schale.replace(/_/g, ' ')
          + ' &middot; calculated ' + String(lauf.zeit).replace('T', ' ').slice(0, 16)
          // Read from the result, not from the dropdown: what is clicked
          // only takes effect on the next run.
          + ' &middot; ' + String(lauf.methode || 'method unknown').replace(/_/g, ' ')
          + '</div>';
} else {
    // The empty state is the one place where explaining is allowed: nothing
    // stands here anyway, nobody is interrupted, and the steps are where
    // they are carried out. A tutorial put in front would be skipped and
    // forgotten - this text disappears by itself as soon as the first
    // result is there.
    html += '<div class="sdi-zahl" style="color:var(--grau);font-size:34px">'
          + 'No footprint yet</div>'
          // The text sits in a wrapper of its own. The row is a flex
          // container, and inside one every child becomes an item of its
          // own: "Press", the bold "Calculate the footprint" and the rest
          // stood side by side instead of forming a sentence. Two children
          // per row - number and text - and the wrapping is right again.
          + '<div class="sdi-schritte">'
          + '<div><span>1</span><p>Choose the product and the impact method '
          + 'below.</p></div>'
          + '<div><span>2</span><p>Press <strong>Calculate the footprint</strong>. '
          + 'It collects ERP, simulation and measured machine data, checks '
          + 'each step and then calculates &mdash; about a minute.</p></div>'
          + '<div><span>3</span><p>The result appears here, split by part, with '
          + 'a link into each administration shell.</p></div>'
          + '</div>';
}
const datenStand = flow.get('datenStand') || {};
let veraltet = false;
if (lauf && lauf.zeit) {
    for (const s of Object.keys(datenStand)) {
        if (String(datenStand[s]) > String(lauf.zeit)) { veraltet = true; }
    }
}
if (veraltet) {
    chips += '<span class="sdi-chip" style="background:rgba(255,159,10,0.15);'
           + 'color:#b45309">recalculate</span>';
}
html += '<div class="sdi-chips">' + chips + '</div>';

if (montage && montage.stueck) {
    let teile = '';
    for (const k of (montage.teile || [])) {
        teile += '<div class="sdi-leise">' + k.artikel + ' &middot; <code>'
               + k.nummer + '</code></div>';
    }
    html += '<details class="sdi-hilfe"><summary>Piece <code>'
          + montage.stueck + '</code>'
          + (montage.teile && montage.teile.length
              ? ' &mdash; built from ' + montage.teile.length + ' recorded parts'
              : '')
          + '</summary>'
          + '<p class="sdi-leise">Booked on manufacturing order '
          + montage.auftrag + (montage.zeit
              ? ', ' + String(montage.zeit).replace('T', ' ').slice(0, 16) : '')
          + '. These parts are recorded as installed in this piece; their '
          + 'measured production energy therefore belongs to it.</p>'
          + teile + '</details>';
}
html += '</div>';
msg.payload = html;
// The button at the top needs only one piece of information: is there a
// result already? After that it reads "Recalculate" instead of
// "Calculate".
return [msg, { topic: 'gerechnet', payload: !!lauf }];

// Reset the display only, not the data. The shells are left untouched; the polling tick fills the view again by itself.
flow.set('ergebnisse', []);
return msg;

// Shows errors in the user interface rather than only in the editor log.
//
// What matters is not that an error occurred but what caused it. "Request
// error" on its own helps nobody; the address and a hint say which service
// is missing.
flow.set('letzterFehler', Date.now());
const fehler = msg.error || {};
const knoten = (fehler.source || {}).name || 'unknown step';
const grund = fehler.message || String(msg.payload || 'no reason given');
const adresse = msg.url || '';

const HINWEISE = [
    [/ECONNREFUSED|ENOTFOUND|RequestError/i,
     'The service does not answer. Is it running, and is its address in .env right?'],
    [/404/, 'The server answers but does not know this identifier.'],
    [/timeout/i, 'The service answers too slowly. openLCA can take minutes.'],
    [/401|403/, 'The credentials were refused.']
];
let hinweis = '';
for (const e of HINWEISE) {
    if (e[0].test(grund) || e[0].test(adresse)) { hinweis = e[1]; break; }
}

msg.payload = '<div class="sdi"><div class="sdi-hinweis sdi-hinweis-fehler">'
    + '<span class="sdi-punkt" style="background:var(--schlecht);margin-top:6px"></span>'
    + '<span><strong>' + knoten + '</strong> — ' + String(grund).substring(0, 200)
    + (adresse ? '<div class="sdi-leise" style="margin-top:4px">'
                 + '<code>' + adresse + '</code></div>' : '')
    + (hinweis ? '<div style="margin-top:6px">' + hinweis + '</div>' : '')
    + '</span></div></div>';
return msg;
